"use client";

import React, { useMemo, useRef } from "react";
import { Canvas, useFrame } from "@react-three/fiber";
import { Html, Line, OrbitControls } from "@react-three/drei";
import * as THREE from "three";
import { SkillCategory, SkillItem } from "@/types/portfolio";

interface SkillConstellationProps {
  skills: SkillItem[];
  selectedSkillId: string;
  activeCategory: SkillCategory | "All";
  onSelectSkill: (id: string) => void;
  accent: string;
  accentSecondary: string;
  reducedMotion: boolean;
}

const CATEGORY_ANGLES: Record<SkillCategory, number> = {
  Languages: 0,
  "Frontend & Motion": Math.PI * 0.5,
  "Systems & CS": Math.PI,
  "DevOps & Tooling": Math.PI * 1.5,
};

interface PositionedNode {
  skill: SkillItem;
  pos: [number, number, number];
  hubPos: [number, number, number];
}

function ConstellationGraph({
  skills,
  selectedSkillId,
  activeCategory,
  onSelectSkill,
  accent,
  accentSecondary,
  reducedMotion,
}: SkillConstellationProps) {
  const groupRef = useRef<THREE.Group>(null);

  const nodes = useMemo<PositionedNode[]>(() => {
    const grouped: Record<SkillCategory, SkillItem[]> = {
      Languages: [],
      "Frontend & Motion": [],
      "Systems & CS": [],
      "DevOps & Tooling": [],
    };
    skills.forEach((s) => {
      grouped[s.category]?.push(s);
    });

    const result: PositionedNode[] = [];
    (Object.keys(grouped) as SkillCategory[]).forEach((cat) => {
      const items = grouped[cat];
      const baseAngle = CATEGORY_ANGLES[cat];
      const hubRadius = 1.65;
      const hubPos: [number, number, number] = [
        Math.cos(baseAngle) * hubRadius,
        ((baseAngle % Math.PI) === 0 ? 0.35 : -0.35),
        Math.sin(baseAngle) * hubRadius,
      ];

      items.forEach((skill, idx) => {
        const spread = items.length > 1 ? (idx / (items.length - 1) - 0.5) * 1.2 : 0;
        const angle = baseAngle + spread;
        const radius = 3.1 + (idx % 2) * 0.55;
        const yOffset = ((idx % 3) - 1) * 0.72 + hubPos[1] * 0.4;
        result.push({
          skill,
          hubPos,
          pos: [Math.cos(angle) * radius, yOffset, Math.sin(angle) * radius],
        });
      });
    });

    return result;
  }, [skills]);

  useFrame((_, delta) => {
    if (groupRef.current && !reducedMotion) {
      groupRef.current.rotation.y += Math.min(delta, 0.05) * 0.09;
    }
  });

  return (
    <group ref={groupRef}>
      {/* Central origin node */}
      <mesh>
        <octahedronGeometry args={[0.38, 0]} />
        <meshStandardMaterial
          color={accent}
          emissive={accent}
          emissiveIntensity={0.8}
          wireframe
        />
      </mesh>

      {nodes.map(({ skill, pos, hubPos }) => {
        const isSelected = skill.id === selectedSkillId;
        const isCategoryMatch = activeCategory === "All" || skill.category === activeCategory;
        const nodeColor = isSelected ? "#FFFFFF" : isCategoryMatch ? accent : "#475569";
        const lineOpacity = isSelected ? 0.85 : isCategoryMatch ? 0.28 : 0.08;

        return (
          <group key={skill.id}>
            <Line
              points={[[0, 0, 0], hubPos, pos]}
              color={isSelected ? accentSecondary : accent}
              lineWidth={isSelected ? 1.8 : 1}
              transparent
              opacity={lineOpacity}
            />
            <mesh
              position={pos}
              onClick={(e) => {
                e.stopPropagation();
                onSelectSkill(skill.id);
              }}
              onPointerOver={() => {
                document.body.style.cursor = "pointer";
              }}
              onPointerOut={() => {
                document.body.style.cursor = "default";
              }}
            >
              <sphereGeometry args={[isSelected ? 0.21 : 0.14, 20, 20]} />
              <meshStandardMaterial
                color={nodeColor}
                emissive={isSelected ? accentSecondary : accent}
                emissiveIntensity={isSelected ? 1.3 : isCategoryMatch ? 0.55 : 0.12}
              />
              <Html
                position={[0, 0.28, 0]}
                center
                distanceFactor={8}
                style={{ pointerEvents: "none" }}
              >
                <div
                  className={`whitespace-nowrap rounded-full border px-2 py-0.5 text-[10px] font-mono tracking-tight transition-all ${
                    isSelected
                      ? "border-sky-300 bg-slate-900/95 text-white shadow-lg"
                      : isCategoryMatch
                      ? "border-slate-700/80 bg-slate-950/80 text-slate-200"
                      : "border-slate-800/40 bg-slate-950/40 text-slate-500"
                  }`}
                >
                  {skill.name}
                </div>
              </Html>
            </mesh>
          </group>
        );
      })}
    </group>
  );
}

export default function SkillConstellation(props: SkillConstellationProps) {
  return (
    <div className="relative h-[420px] w-full overflow-hidden rounded-2xl border border-slate-800/80 bg-slate-950/60 backdrop-blur-xl">
      <div className="pointer-events-none absolute left-4 top-3 z-10 flex items-center gap-2 rounded-full border border-slate-800 bg-slate-900/80 px-3 py-1 text-[11px] font-mono text-slate-300">
        <span className="h-2 w-2 rounded-full bg-sky-400 animate-pulse" />
        3D Skill Graph · Drag to orbit · Click any node
      </div>
      <Canvas
        camera={{ position: [0, 2.2, 7.6], fov: 45 }}
        dpr={[1, 2]}
        gl={{ antialias: true, alpha: true }}
      >
        <ambientLight intensity={0.7} />
        <pointLight position={[6, 6, 6]} intensity={2} color={props.accent} />
        <pointLight position={[-6, -4, -4]} intensity={1.2} color={props.accentSecondary} />
        <ConstellationGraph {...props} />
        <OrbitControls enableZoom={false} enablePan={false} autoRotate={false} />
      </Canvas>
    </div>
  );
}
